spec.definitions:
def pow2 : Nat → Nat | 0 => 1 | (a+1) => 2 * pow2 a
def isOddDivisor (d : Nat) : Bool := d % 2 == 1 && d ∣ (2 ^ 0)
def check_k1_aux (a : Nat) : Bool := (2 ^ a) % 2 == 0 && (2 ^ a) / 2 == pow2 (a-1) || a == 0
def check_k1 (N : Nat) : Bool := (List.range (N+1)).all (fun a => pow2 a % 2 == 0 || pow2 a == 1)
